describe('Public Profile Page', () => {
    beforeEach(() => {
        cy.visit('/profile/public'); // Adjust the URL as necessary
    });

    it('should display the user\'s shared information correctly', () => {
        cy.get('.profile-name').should('contain', 'John Doe'); // Replace with actual user name
        cy.get('.profile-bio').should('contain', 'This is my bio.'); // Replace with actual bio
        cy.get('.profile-email').should('contain', 'john.doe@example.com'); // Replace with actual email
        cy.get('.profile-phone').should('contain', '123-456-7890'); // Replace with actual phone number
    });

    it('should handle the case when no information is shared', () => {
        cy.get('.profile-name').should('not.exist');
        cy.get('.profile-bio').should('not.exist');
        cy.get('.profile-email').should('not.exist');
        cy.get('.profile-phone').should('not.exist');
        cy.get('.no-info-message').should('be.visible').and('contain', 'No information shared yet.');
    });
});
